import path from"path";import{getGlobalVariables,setGlobalVariables}from"./setup-global-variables.js";import{isPro}from"../common/other-tools.js";export function injectionResourcesPath(){const a=getGlobalVariables("serverRootDirPath"),t=path.join(a,"../data",isPro()?"pro":"dev");setGlobalVariables("serverDataRootDirPath",t),setGlobalVariables("rssXmlPath",path.join(t,"rss.xml")),setGlobalVariables("sitemapXmlPath",path.join(t,"sitemap.xml")),setGlobalVariables("webAdminDistDirPath",path.join(a,"../web-admin/dist")),setGlobalVariables("webAssetsDistDirPath",path.join(a,"../web/dist"))}